-- =========================================================================
-- D25 — les 28 fichiers Word/ODT d'Anarchief.org entrent dans la file NUMDIF,
-- validés, au cas que Xavier a décidé
-- =========================================================================
-- Date     : 2026-10-23
-- Chantier : documents numériques — REGISTRE §47 (NUMDIF-2 amendé, NUMDIF-6)
-- Auteur   : Claude (assistant·e), pour la coordination
-- Ref      : docs/journal/audits/INVENTAIRE_d25_word_odt_anarchief_2026-10-23.md
--            (liste, cas proposés, décisions) ;
--            20261023130916_d25_word_et_odt_admis_en_telechargement (l'outil)
--
-- POURQUOI
--   Décision de Xavier du 23/10/2026 (questionnaire D25) : les fichiers Word et
--   ODT d'Anarchief, écartés le 15/10 faute de format admis, se versent en
--   téléchargement seulement. Groupes 1 et 2 comme proposé ; groupes 3 et 4 en
--   (c), sauf les deux textes de PP, en (a) comme son PDF du lot des petits
--   auteurs. Bilan : 12 publics (9 en (a), 3 en (d)), 16 restreints (c).
--
-- CE QUE FAIT LE PAQUET (donnée seulement)
--   28 candidats « valide » dans ingest.digital_candidates, bibliothèque
--   Anarchief.org, décidés par Xavier : l'URL du fichier sur le wiki, la page
--   (curid), le nom, le SHA-1 et la taille rendus par l'API MediaWiki du wiki
--   (relevés le 23/10 ; le SHA-256 se calcule au premier téléchargement, NUMDIF-4),
--   le cas, et une justification NUMDIF-6 (validation par lot). Rien n'est
--   versé ici : le versement passe par la fonction Edge
--   deposit-digital-candidate, avec la session (aal2) de l'administration du
--   réseau, qui télécharge, vérifie l'empreinte et le format, et crée la
--   ressource « documento ».
--   (a) : le lot et la remarque de J/M du PDF de la même notice (ou, pour PP,
--   de son PDF du même lot) ; « déclaration par lot » comme page de mention.
--   (d) : NUMDIF-2 amendé, auteur mort depuis plus de 70 ans, original sans
--   traduction. (c) : le doute va au restreint ; 15 d'entre eux font l'objet
--   d'une question à J/M (brouillon dans l'inventaire, à envoyer par Xavier) ;
--   Constandse, lettre « C », non.
--
-- CHECKLIST DOCTRINE
--   [x] Donnée : critère et compte gardés (0 au banc, sans la bibliothèque ;
--       28 en production, sinon échec) ; rejouable (ON CONFLICT DO NOTHING)
--   [x] Chaque notice est détenue par Anarchief.org, sinon échec
--   [x] Aucun objet créé, aucun droit touché
-- =========================================================================

BEGIN;

DO $d25_donnees$
DECLARE
  c_anarchief constant uuid := '1bb157fd-4d1f-415b-9e5d-490f4f8d0895';
  c_xavier    constant uuid := 'd6710372-e5e5-4608-800b-99a26817c677';
  c_marque    constant text := 'D25 : fichier Word/ODT, en téléchargement seulement';
  v_n int; v_a int; v_d int; v_c int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.libraries WHERE id = c_anarchief) THEN
    RAISE NOTICE 'D25 : bibliothèque Anarchief.org absente (banc), rien à faire.';
    RETURN;
  END IF;

  INSERT INTO ingest.digital_candidates (
    book_id, library_id, status, file_url, page_url, source_name, source_identifier, original_filename,
    sha1, file_size_bytes, proposed_verdict, proposed_case, proposed_mention, proposed_mention_page,
    verdict, source_case, justification, rights_mention, rights_mention_page,
    tool_notes, proposed_by, proposed_at, decided_by, decided_at)
  SELECT v.book_id, c_anarchief, 'valide', v.file_url, 'https://anarchief.org/w/index.php?curid=' || v.page_id,
         'Anarchief.org', v.nom, v.nom,
         v.sha1, v.taille, 'meme_edition', v.cas, v.mention, v.page,
         'meme_edition', v.cas, v.justif, v.mention, v.page,
         jsonb_build_object('d25', jsonb_build_object(
