    ) AS v(book_id, page_id, file_url, nom, sha1, taille, cas, justif, mention, page)
   WHERE EXISTS (SELECT 1 FROM public.book_holdings h WHERE h.book_id = v.book_id AND h.library_id = c_anarchief)
  ON CONFLICT (library_id, book_id, file_url) DO NOTHING;

  SELECT count(*),
         count(*) FILTER (WHERE source_case = 'diffusion_autorisee'),
         count(*) FILTER (WHERE source_case = 'domaine_public'),
         count(*) FILTER (WHERE source_case = 'statut_inconnu')
    INTO v_n, v_a, v_d, v_c
    FROM ingest.digital_candidates
   WHERE library_id = c_anarchief AND position(c_marque IN justification) > 0
     AND file_url ~* '\.(docx?|odt)$' AND status IN ('valide', 'verse');
  IF (v_n, v_a, v_d, v_c) IS DISTINCT FROM (28, 9, 3, 16) THEN
    RAISE EXCEPTION 'D25 : % candidats Word/ODT (dont % (a), % (d), % (c)) — 28 attendus (9, 3, 16) ; une notice n''est plus détenue par Anarchief.org ?',
      v_n, v_a, v_d, v_c;
  END IF;
  RAISE NOTICE 'D25 : 28 candidats Word/ODT validés (9 (a), 3 (d), 16 (c)), à verser.';
END
$d25_donnees$;

COMMIT;
